/// The caller retains this identity across a retry; a separate create mints another.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NewTask {
    pub id: crate::durable::TaskId,
    pub project_id: crate::durable::ProjectId,
    pub title: String,
    pub description: String,
}

TaskCommand::Create {
    wave,
    title,
    notes,
    creation_id,
    json,
} => {
    let report = match notes {
        Some(notes) => Some(notes.clone()),
        None => piped_task_report()?,
    };
    let identity = creation_id.clone().unwrap_or_default();
    eprintln!("Creation identity: {identity}; retain --creation-id {identity} when retrying this request");
    let issue = loopflow::ops::task::task_create(
        repo,
        wave.as_deref(),
        title.clone(),
        report,
        identity,
    )?;
    if *json {
        println!("{}", serde_json::to_string_pretty(&issue)?);
    } else {
        println!("{} · {}", issue.identifier, issue.name);
    }
    Ok(())
}

pub fn create_local_task(&self, input: &crate::planning::NewTask) -> StoreResult<Task> {
    let mut conn = self.conn.lock().expect("store mutex poisoned");
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let intent: Option<(String, String, String)> = tx
        .query_row(
            "SELECT project_id,title,description FROM task_creation_intents WHERE task_id=?1",
            [input.id.as_str()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if let Some((project, title, description)) = intent {
        if project != input.project_id.as_str()
            || title != input.title
            || description != input.description
        {
            return Err(StoreError::InvalidData(
                "creation identity already belongs to a different request".into(),
            ));
        }
        return task_on(&tx, &input.id)?.ok_or(StoreError::NotFound);
    }
    if input.title.trim().is_empty() {
        return Err(StoreError::InvalidData("Task title cannot be empty".into()));
    }
    let wave_id: WaveId = tx.query_row(
        "SELECT wave_id FROM projects WHERE id=?1",
        [input.project_id.as_str()],
        |row| row.get(0),
    )?;
    if super::local_planning::project_authority_on(&tx, &input.project_id)?
        != crate::planning::PlanningAuthority::Local
    {
        return Err(StoreError::InvalidAuthority(
            "this Project's planning is owned by Linear".into(),
        ));
    }
    super::durable::require_selected_project(&tx, &input.project_id)?;
    let now = OffsetDateTime::now_utc();
    let task = Task {
        id: input.id.clone(),
        plan: TaskPlan {
            revision: 0,
            linear_id: None,
            identifier: format!("lf-{}", input.id.as_str().trim_start_matches("task_")),
            title: input.title.clone(),
            description: input.description.clone(),
            pm_snapshot_synced_at: None,
        },
        pm_writeback: PmWritebackState::Current,
        wave_id,
        project_id: input.project_id.clone(),
        worktree: None,
        workspace_slug: String::new(),
        agent: None,
        abandon_intent: None,
        created_at: now,
        updated_at: now,
        observation: crate::work::task::Observation::NotRequired,
    };
    validate_task(&task)?;
    insert_task_row(&tx, &task)?;
    tx.execute("UPDATE tasks SET planning_rank=COALESCE((SELECT max(planning_rank)+1 FROM tasks WHERE project_id=?2 AND id!=?1),0) WHERE id=?1",params![task.id.as_str(),task.project_id.as_str()])?;
    tx.execute(
        "INSERT INTO task_creation_intents(task_id, project_id, title, description)
         VALUES(?1, ?2, ?3, ?4)",
        params![
            input.id.as_str(),
            input.project_id.as_str(),
            input.title,
            input.description
        ],
    )?;
    let task = task_on(&tx, &input.id)?.ok_or(StoreError::NotFound)?;
    tx.commit()?;
    Ok(task)
}

pub fn task_create(
    repo: &Path,
    wave: Option<&str>,
    title: Option<String>,
    report: Option<String>,
    identity: crate::durable::TaskId,
) -> OpsResult<crate::pm::PmItem> {
    let input = resolve_task_create_input(title.as_deref(), report.as_deref())?;
    let main = crate::engine::worktrees::main_repo_root(repo).map_err(task_error)?;
    let personal = match wave {
        Some(wave) if wave.starts_with("personal:") => {
            wave.strip_prefix("personal:").map(str::to_string)
        }
        selected => {
            match crate::work::wave::context::resolve_managed_wave_sync(Some(&main), selected) {
                Ok(wave) => wave.slug().strip_prefix("personal:").map(str::to_string),
                Err(crate::work::wave::context::WaveResolveError::NoContext)
                    if selected.is_none() =>
                {
                    Some("inbox".into())
                }
                Err(error) => return Err(task_error(error)),
            }
        }
    };
    if let Some(name) = personal {
        return block_on_task(async {
            let store = super::pm::pm_store().await?;
            let canonical =
                crate::repository::CanonicalRepo::discover(&main).map_err(task_error)?;
            let project = store
                .sqlite
                .ensure_personal_project(&canonical.to_string(), &name)
                .map_err(task_error)?;
            let wave = store
                .get_wave(&project.wave_id)
                .await
                .map_err(task_error)?
                .ok_or_else(|| task_error("personal Wave is missing"))?;
            let acquisition = super::pm::lock_wave_planning(&wave).await?;
            let creation_project = match store
                .sqlite
                .local_task_creation_project(&identity)
                .map_err(task_error)?
            {
                Some(id) => {
                    let original = store
                        .get_project(&id)
                        .await
                        .map_err(task_error)?
                        .ok_or_else(|| task_error("creation Project is missing"))?;
                    if original.wave_id != project.wave_id {
                        return Err(task_error("creation identity belongs to a different Wave"));
                    }
                    id
                }
                None => crate::durable::ProjectId::parse(
                    &super::project::current_project(&store, &wave)?.id,
                )
                .map_err(task_error)?,
            };
            let task = store
                .create_local_task(
                    &crate::planning::NewTask {
                        id: identity,
                        project_id: creation_project,
                        title: input.title,
                        description: input.report,
                    },
                    acquisition,
                )
                .await
                .map_err(task_error)?;
            local_task_item(&store, &task)
        });
    }
    let project =
        crate::ops::task_pm::resolve_current_project(&main, wave, crate::ops::pm::PmRefresh::Auto)?;

