    pub fn update_local_project_content(
        &self,
        project: &ProjectId,
        content: &crate::pm::ProjectContent,
        workflow_definition: Option<&str>,
    ) -> StoreResult<()> {
        content
            .validate()
            .map_err(|error| StoreError::InvalidData(error.to_string()))?;
        let mut conn = self.conn.lock().expect("store mutex poisoned");
        let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
        if project_authority_on(&tx, project)? != PlanningAuthority::Local {
            return Err(StoreError::InvalidAuthority(
                "this Project's planning is owned by Linear".into(),
            ));
        }
        if let Some(definition) = workflow_definition {
            let name = content
                .workflow
                .strip_prefix("personal:")
                .filter(|name| !name.is_empty())
                .ok_or_else(|| {
                    StoreError::InvalidData("a stored Workflow uses personal:<name>".into())
                })?;
            tx.execute(
                "INSERT INTO personal_workflows(wave_id,name,content)
                SELECT wave_id,?2,?3 FROM projects WHERE id=?1
                ON CONFLICT(wave_id,name) DO UPDATE SET content=excluded.content",
                params![project.as_str(), name, definition],
            )?;
        }
        tx.execute(
            "UPDATE projects SET project_prompt_context=?2,workflow=?3,updated_at=?4 WHERE id=?1",
            params![
                project.as_str(),
                crate::pm::render_project_content(content),
                content.workflow,
                now_unix()
            ],
        )?;
        tx.commit()?;
        Ok(())
    }

struct PersonalWorkflowEditor: View {
    let model: WorkModel
    let wave: WaveSnapshot
    let name: String
    @Environment(\.dismiss) private var dismiss
    @State private var content = ""
    @State private var ready = false
    @State private var saving = false
    @State private var error: String?

    var body: some View {
        VStack(alignment: .leading, spacing: Spacing.md) {
            Text("Edit \(name)").font(Typography.sectionTitle(22))
            TextEditor(text: $content).font(.system(.body, design: .monospaced))
                .disabled(!ready || saving)
                .accessibilityIdentifier("personal-workflow-content")
            if let error { Text(error).foregroundStyle(Color.statusWarning) }
            HStack {
                Button("Cancel") { dismiss() }.keyboardShortcut(.cancelAction)
                Spacer()
                Button("Save") { Task {
                    saving = true
                    defer { saving = false }
                    do {
                        try await model.savePersonalWorkflow(name, content: content, wave: wave)
                        dismiss()
                    } catch { self.error = error.localizedDescription }
                } }.disabled(!ready || saving).keyboardShortcut(.defaultAction)
            }
        }
        .padding(24).frame(width: 640, height: 480)
        .interactiveDismissDisabled(saving)
        .task {
            do { content = try await model.workflowSource(name, wave: wave); ready = true }
            catch { self.error = error.localizedDescription }
        }
    }
}

pub fn place_task(
    &self,
    task_id: &TaskId,
    worktree: &std::path::Path,
    workspace_slug: &str,
    pr: &TaskPr,
) -> StoreResult<Task> {
    let _admission = self.lock_checkout(worktree)?;
    let mut conn = self.conn.lock().expect("store mutex poisoned");
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let mut task = task_on(&tx, task_id)?.ok_or(StoreError::NotFound)?;
    if task.worktree.is_some() {
        return Ok(task);
    }
    if super::durable::task_state_in(&tx, task_id)?.is_terminal() {
        return Err(StoreError::InvalidAuthority(
            "terminal Task cannot allocate a checkout".into(),
        ));
    }
    super::durable::require_selected_project(&tx, &task.project_id)?;
    require_task_not_deleted(&tx, &task)?;
    task.worktree = Some(worktree.to_path_buf());
    task.workspace_slug = workspace_slug.to_string();
    validate_initial_task_pr(&task, pr)?;
    tx.execute(
        "UPDATE tasks SET worktree=?2,workspace_slug=?3,updated_at=?4 WHERE id=?1",
        params![
            task_id.as_str(),
            worktree.display().to_string(),
            workspace_slug,
            now_unix()
        ],
    )?;
    inherit_task_placement(&tx, &task)?;
    insert_task_pr(&tx, pr)?;
    insert_task_event_in(
        &tx,
        task_id,
        &TaskEventKind::WorktreeInitializing {
            pr_id: pr.id.clone(),
            sequence: pr.sequence,
            branch: pr.branch.clone(),
            path: worktree.display().to_string(),
            base_commit: pr.base_commit.clone(),
        },
    )?;
    let task = task_on(&tx, task_id)?.ok_or(StoreError::NotFound)?;
    tx.commit()?;
    Ok(task)
}

async fn reach_end(
    store: &SharedStore,
    task: &mut Task,
    how: EndMove,
    note: Option<&str>,
    options: &EndOptions,
) -> OpsResult<bool> {
    match task_work_status(store, task).await? {
        WorkStatus::Done => {
            reconcile_task_completion(store, task).await?;
            cleanup_completed_task(store, task).await?;
            return Ok(true);
        }
        WorkStatus::Abandoned => {
            return Err(task_error(format!(
                "Task {} is abandoned and cannot be completed",
                task.plan.identifier
            )))
        }
        WorkStatus::Ready => {}
    }
    let conflict = planning_conflict(store, task).await?;
    if let Some(conflict) = conflict.as_ref().filter(|_| !options.force) {
        return Err(task_error(conflict));
    }
    reconcile_task_pr_observation(store, task, crate::ops::pr::PrReadFreshness::Cached).await?;
    // An edge that runs nothing lands nothing: the Task ends as it stands and
    // keeps its checkout, so what is uncommitted there is not at risk.
    let keeps_checkout = matches!(how, EndMove::Choose { .. });
    if !keeps_checkout
        && task.worktree.is_some()
        && !is_clean(task.worktree()?)
            .map_err(|error| task_error(format!("failed to inspect Task worktree: {error}")))?
    {
        return Err(task_error(
            "Task worktree has uncommitted changes; publish or explicitly abandon them first",
        ));
    }
    // The completion gate requires every active PR to be settled. Do not
    // bypass that fact or infer merge from a green head.
    let gate = task_completion_gate(store, task).await?;
    if let Some(refusal) = gate.refusal(&task.plan.identifier) {
        return Err(task_error(refusal));
    }
    reconcile_pm_writeback(store, task, None).await?;

// … intervening source omitted …

    // Every other condition is now proven, so an empty unpublished PR is
    // retired in the completion transaction. Retaining its branch identity
    // lets cleanup retry after a crash without guessing what it may delete.
    if !store
        .complete_task(
            task,
            gate.discardable_successor.as_ref(),
            how,
            forced.as_deref().or(note),
        )
        .await
        .map_err(|error| task_error(format!("failed to complete Task: {error}")))?
    {
        return Ok(false);
    }
    if keeps_checkout {
        eprintln!(
            "Task {} is complete; retained its checkout.",
            task.plan.identifier
        );
        return Ok(true);
    }
    cleanup_completed_task(store, task).await?;
    Ok(true)
}

